def is_line_l(comp):
    rs=[r for r,c in comp]; cs=[c for r,c in comp]
    # A one-cell-thick L, including its corner.
    rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
    if len(comp) != (rmax-rmin+1)+(cmax-cmin+1)-1: return None
    pts=set(comp)
    for vr in (rmin,rmax):
        for hc in (cmin,cmax):
            expected={(r,hc) for r in range(rmin,rmax+1)} | {(vr,c) for c in range(cmin,cmax+1)}
            if pts == expected:
                # horizontal arm is at vr; vertical stem is at hc
                return (vr,hc,rmin,rmax,cmin,cmax)
    return None

def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    guides=[]
    for color in set(x for row in g for x in row)-{bg}:
        for comp in components(g,color):
            sh=is_line_l(comp)
            if sh and len(comp)>=5 and sh[3]>sh[2] and sh[5]>sh[4]:guides.append((color,comp,sh))
    if not guides:return g
    color,guide,(vr,hc,rmin,rmax,cmin,cmax)=max(guides,key=lambda x:len(x[1]))
    hlen=cmax-cmin+1
    candidates=[]
    for comp in components(g,3):
        if len(comp)==hlen:
            rs=[r for r,c in comp];cs=[c for r,c in comp]
            if len(set(cs))==1:
                d=min(abs(r-vr)+abs(c-hc) for r,c in comp)
                candidates.append((d,comp))
    if candidates:
        for r,c in min(candidates,key=lambda x:x[0])[1]:g[r][c]=color
    return g

